import { readFileSync } from "node:fs";

const SUPPORTED_SCHEMA = 4;
const SCHEMA_PATTERN = /^cfg-schema-v(\d+)$/;

function readLayerFile(path) {
  let text;
  try {
    text = readFileSync(path, "utf8");
  } catch (err) {
    if (err.code === "ENOENT") return null;
    throw err;
  }
  return JSON.parse(text);
}

function checkSchemaVersion(data, layer, path) {
  const declared = data.schemaVersion;
  if (declared === undefined) return;
  const match = SCHEMA_PATTERN.exec(String(declared));
  if (!match) {
    throw new Error(`config ${layer} (${path}): unrecognised schemaVersion "${declared}"`);
  }
  if (Number(match[1]) > SUPPORTED_SCHEMA) {
    throw new Error(
      `config ${layer} (${path}): declares ${declared}, newer than supported cfg-schema-v${SUPPORTED_SCHEMA}`,
    );
  }
}

/**
 * Load config in three layers: defaults, project file, user file.
 * The merged result is checked against `schema` (key -> typeof name).
 * Unknown keys warn and are dropped; files declaring a schema newer than
 * cfg-schema-v4 are refused.
 *
 * @returns {{ values: object, sources: object, warnings: string[] }}
 *   `sources[key]` names the layer that set each value.
 */
export function loadConfig({ defaults, schema, projectFile, userFile, warn = console.warn }) {
  const values = {};
  const sources = {};
  const warnings = [];

  const layers = [{ name: "defaults", data: defaults }];
  for (const [name, path] of [["project", projectFile], ["user", userFile]]) {
    if (!path) continue;
    const data = readLayerFile(path);
    if (data === null) continue;
    checkSchemaVersion(data, name, path);
    layers.push({ name, data, path });
  }

  for (const { name, data, path } of layers) {
    for (const [key, value] of Object.entries(data)) {
      if (key === "schemaVersion") continue;
      if (!Object.hasOwn(schema, key)) {
        const where = path ? `${name} (${path})` : name;
        const message = `config: unknown key "${key}" in ${where}, ignored`;
        warnings.push(message);
        warn(message);
        continue;
      }
      values[key] = value;
      sources[key] = name;
    }
  }

  for (const [key, type] of Object.entries(schema)) {
    if (!(key in values)) continue;
    const actual = Array.isArray(values[key]) ? "array" : typeof values[key];
    if (actual !== type) {
      throw new Error(`config: "${key}" from ${sources[key]} must be ${type}, got ${actual}`);
    }
  }

  return { values, sources, warnings };
}
