import { readFile } from "node:fs/promises";

export const SCHEMA_VERSION = 4;
const VERSION_RE = /^cfg-schema-v(\d+)$/;

async function readLayer(path) {
  if (!path) return null;
  try {
    return JSON.parse(await readFile(path, "utf8"));
  } catch (err) {
    if (err.code === "ENOENT") return null;
    throw new Error(`config: cannot read ${path}: ${err.message}`);
  }
}

function checkVersion(data, layer, path) {
  const declared = data.$schema;
  if (declared === undefined) return;
  const m = VERSION_RE.exec(String(declared));
  if (!m) throw new Error(`config: ${layer} file ${path} declares unknown schema "${declared}"`);
  if (Number(m[1]) > SCHEMA_VERSION) {
    throw new Error(
      `config: ${layer} file ${path} declares ${declared}, newer than cfg-schema-v${SCHEMA_VERSION}`,
    );
  }
}

/**
 * Loads config in three layers: defaults, then project file, then user file.
 * The merged result is checked against `schema` ({ key: { type } }).
 * Unknown keys warn (naming key and layer) and never fail.
 * Returns { values, sources, warnings }; sources[key] names the layer that set it.
 */
export async function loadConfig({ defaults = {}, schema, projectPath, userPath, warn = console.warn } = {}) {
  if (!schema) throw new Error("config: schema is required");
  const values = {};
  const sources = {};
  const warnings = [];

  const layers = [
    ["defaults", null, defaults],
    ["project", projectPath, await readLayer(projectPath)],
    ["user", userPath, await readLayer(userPath)],
  ];

  for (const [layer, path, data] of layers) {
    if (!data) continue;
    if (path) checkVersion(data, layer, path);
    for (const [key, value] of Object.entries(data)) {
      if (key === "$schema") continue;
      if (!Object.hasOwn(schema, key)) {
        const msg = `config: unknown key "${key}" in ${layer} layer${path ? ` (${path})` : ""}`;
        warnings.push(msg);
        warn(msg);
        continue;
      }
      values[key] = value;
      sources[key] = layer;
    }
  }

  for (const [key, value] of Object.entries(values)) {
    const { type } = schema[key];
    const actual = Array.isArray(value) ? "array" : typeof value;
    if (type && actual !== type) {
      throw new Error(`config: "${key}" from ${sources[key]} layer must be ${type}, got ${actual}`);
    }
  }

  return { values, sources, warnings };
}
