import { readFileSync } from "node:fs";

const SCHEMA_ID = "cfg-schema-v4";
const MAX_SCHEMA_VERSION = 4;

function readLayer(path, layer) {
  let text;
  try {
    text = readFileSync(path, "utf8");
  } catch (err) {
    if (err.code === "ENOENT") return {};
    throw err;
  }
  const data = JSON.parse(text);
  const declared = data.$schema;
  if (declared !== undefined) {
    const match = /^cfg-schema-v(\d+)$/.exec(declared);
    if (!match) throw new Error(`${layer} config ${path}: unrecognized schema "${declared}"`);
    if (Number(match[1]) > MAX_SCHEMA_VERSION) {
      throw new Error(`${layer} config ${path} declares ${declared}, newer than supported ${SCHEMA_ID}`);
    }
  }
  delete data.$schema;
  return data;
}

/**
 * Load config in three layers: built-in defaults, then the project file, then the user file.
 * Returns { values, sources, warnings }; sources[key] names the layer that set the value.
 * `schema` maps each known key to its expected typeof string.
 */
export function loadConfig({ defaults = {}, schema = {}, projectPath, userPath, warn = console.warn } = {}) {
  const layers = [
    ["defaults", defaults],
    ["project", projectPath ? readLayer(projectPath, "project") : {}],
    ["user", userPath ? readLayer(userPath, "user") : {}],
  ];

  const values = {};
  const sources = {};
  const warnings = [];
  for (const [layer, data] of layers) {
    for (const [key, value] of Object.entries(data)) {
      if (!Object.hasOwn(schema, key)) {
        const msg = `unknown config key "${key}" in ${layer} layer (ignored)`;
        warnings.push(msg);
        warn(msg);
        continue;
      }
      values[key] = value;
      sources[key] = layer;
    }
  }

  for (const [key, type] of Object.entries(schema)) {
    if (key in values && typeof values[key] !== type) {
      throw new Error(`config key "${key}" from ${sources[key]} layer must be ${type}, got ${typeof values[key]}`);
    }
  }

  return { values, sources, warnings };
}
